# ruff: noqa  (SVG-drawing scripts: long path strings are clearer unwrapped)
"""Generate assets/chonga-map.svg: the continent of Chonga, seen from above."""

import math, random

random.seed(7)
out = []
w = out.append

w("""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="1024" height="1024">
  <!-- ChongaBot avatar: the Land of Chonga from above. Generated by scripts/gen_map.py;
       north = Chongalayas, west = Whispering Woods, east = Mudlands, middle = the Rivers,
       south = the Chonga Coast, and the Great Above (stars) around the rim. -->
  <defs>
    <radialGradient id="sea" cx="50%" cy="50%" r="60%">
      <stop offset="0" stop-color="#2f8fc0"/>
      <stop offset="0.62" stop-color="#1d5f9a"/>
      <stop offset="0.86" stop-color="#1a2f6b"/>
      <stop offset="1" stop-color="#140f3a"/>
    </radialGradient>
    <radialGradient id="land" cx="50%" cy="45%" r="55%">
      <stop offset="0" stop-color="#9ed36a"/>
      <stop offset="1" stop-color="#6fae4a"/>
    </radialGradient>
    <linearGradient id="mud" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#a8774a"/>
      <stop offset="1" stop-color="#7d5532"/>
    </linearGradient>
    <linearGradient id="rock" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#8a8fa8"/>
      <stop offset="1" stop-color="#5a5f78"/>
    </linearGradient>
    <clipPath id="isle"><path id="coast" d="CONTINENT"/></clipPath>
  </defs>
  <rect width="1024" height="1024" fill="url(#sea)"/>
""")

# --- the Great Above: stars around the rim
for _ in range(90):
    a = random.uniform(0, 2 * math.pi)
    r = random.uniform(430, 720)
    x, y = 512 + r * math.cos(a), 512 + r * math.sin(a)
    if 0 <= x <= 1024 and 0 <= y <= 1024:
        w(
            f'  <circle cx="{x:.0f}" cy="{y:.0f}" r="{random.uniform(1.5, 4.5):.1f}" fill="#fff6d0" opacity="{random.uniform(0.4, 0.95):.2f}"/>'
        )

# --- continent outline: a lumpy blob
pts = []
n = 28
for i in range(n):
    a = 2 * math.pi * i / n - math.pi / 2
    r = 345 + 38 * math.sin(3 * a + 0.6) + 22 * math.sin(5 * a + 2.1) + random.uniform(-14, 14)
    pts.append((512 + r * math.cos(a) * 1.04, 500 + r * math.sin(a) * 0.98))


def smooth(points):
    d = f"M{(points[-1][0] + points[0][0]) / 2:.0f} {(points[-1][1] + points[0][1]) / 2:.0f}"
    for i, p in enumerate(points):
        q = points[(i + 1) % len(points)]
        d += f" Q{p[0]:.0f} {p[1]:.0f} {(p[0] + q[0]) / 2:.0f} {(p[1] + q[1]) / 2:.0f}"
    return d + " Z"


cont = smooth(pts)
out[0] = out[0].replace("CONTINENT", cont)

# shallows + beach rings
w(
    f'  <path d="{cont}" fill="#5fc3e8" opacity="0.35" transform="translate(512 500) scale(1.09) translate(-512 -500)"/>'
)
w(
    f'  <path d="{cont}" fill="#5fc3e8" opacity="0.35" transform="translate(512 500) scale(1.045) translate(-512 -500)"/>'
)
w(f'  <path d="{cont}" fill="#f3dc96"/>')
w(
    f'  <path d="{cont}" fill="url(#land)" transform="translate(512 490) scale(0.955) translate(-512 -490)"/>'
)

w('  <g clip-path="url(#isle)">')
# Mudlands (east)
w(
    '    <path d="M640 380 Q760 360 900 420 L920 720 Q800 700 700 660 Q660 560 640 380 Z" fill="url(#mud)"/>'
)
for x, y in [(730, 470), (790, 540), (720, 600), (830, 620), (800, 450)]:
    w(f'    <ellipse cx="{x}" cy="{y}" rx="26" ry="10" fill="#5e3d22" opacity="0.5"/>')
# huts of Mudhollow
for x, y in [(760, 500), (800, 505), (780, 575)]:
    w(
        f'    <rect x="{x - 13}" y="{y - 10}" width="26" height="20" fill="#d9a066" stroke="#4a2b14" stroke-width="3"/>'
    )
    w(
        f'    <path d="M{x - 19} {y - 8} L{x} {y - 28} L{x + 19} {y - 8} Z" fill="#c0392b" stroke="#4a2b14" stroke-width="3" stroke-linejoin="round"/>'
    )
# Chonga Coast (south) - sandy strip
w('    <path d="M120 700 Q300 760 512 740 Q720 760 920 690 L920 920 L120 920 Z" fill="#f3dc96"/>')
w(
    '    <path d="M120 700 Q300 760 512 740 Q720 760 920 690" fill="none" stroke="#d9bd6a" stroke-width="6" opacity="0.7"/>'
)
w("  </g>")

# Rivers of Chonga: three rivers from the mountains, meeting in the middle, out to the sea
rivers = [
    "M410 300 Q380 400 450 470 Q500 530 500 600 Q505 700 482 805",
    "M560 280 Q600 380 540 460 Q505 510 500 600",
    "M680 330 Q650 430 600 500 Q540 560 500 600",
]
for i, r in enumerate(rivers):
    w(
        f'  <path d="{r}" fill="none" stroke="#2f8fc0" stroke-width="{26 if i == 0 else 18}" stroke-linecap="round" stroke-linejoin="round"/>'
    )
    w(
        f'  <path d="{r}" fill="none" stroke="#7fd6f5" stroke-width="{10 if i == 0 else 6}" stroke-linecap="round" stroke-linejoin="round" opacity="0.8"/>'
    )
# a gold shimmer: they flow with gold (don't drink it)
w(
    '  <path d="M500 600 Q505 700 482 805" fill="none" stroke="#ffd45c" stroke-width="4" stroke-dasharray="6 18" stroke-linecap="round"/>'
)

# Whispering Woods (west): clusters of round trees
trees = []
for _ in range(70):
    x, y = random.uniform(175, 420), random.uniform(380, 680)
    if (x - 300) ** 2 / 140**2 + (y - 530) ** 2 / 160**2 < 1 and abs(
        x - (400 + (y - 470) * 0.3)
    ) > 30:
        trees.append((x, y))
for x, y in sorted(trees, key=lambda t: t[1]):
    s = random.uniform(16, 24)
    w(f'  <rect x="{x - 3:.0f}" y="{y:.0f}" width="6" height="{s * 0.8:.0f}" fill="#5c3a1e"/>')
    w(
        f'  <circle cx="{x:.0f}" cy="{y:.0f}" r="{s:.0f}" fill="#1f6b3a" stroke="#134a27" stroke-width="3"/>'
    )
    w(
        f'  <circle cx="{x - s * 0.3:.0f}" cy="{y - s * 0.3:.0f}" r="{s * 0.35:.0f}" fill="#2f8f4e"/>'
    )

# Chongalayas (north): a row of peaks, back to front
peaks = [
    (300, 330, 95),
    (410, 300, 120),
    (520, 270, 140),
    (630, 300, 115),
    (735, 335, 90),
    (360, 370, 80),
    (580, 360, 90),
    (470, 375, 75),
    (690, 385, 70),
]
for x, y, h in peaks:
    b = h * 0.85
    w(
        f'  <path d="M{x - b:.0f} {y + h * 0.35:.0f} L{x} {y - h * 0.65:.0f} L{x + b:.0f} {y + h * 0.35:.0f} Z" fill="url(#rock)" stroke="#3c3f55" stroke-width="5" stroke-linejoin="round"/>'
    )
    w(
        f'  <path d="M{x} {y - h * 0.65:.0f} L{x + b:.0f} {y + h * 0.35:.0f} L{x} {y + h * 0.35:.0f} Z" fill="#3c3f55" opacity="0.25"/>'
    )
    sx, sy = b * 0.32, h * 0.32
    w(
        f'  <path d="M{x - sx:.0f} {y - h * 0.65 + sy:.0f} L{x} {y - h * 0.65:.0f} L{x + sx:.0f} {y - h * 0.65 + sy:.0f} L{x + sx * 0.4:.0f} {y - h * 0.65 + sy * 0.75:.0f} L{x:.0f} {y - h * 0.65 + sy * 1.05:.0f} L{x - sx * 0.4:.0f} {y - h * 0.65 + sy * 0.75:.0f} Z" fill="#f4f8ff"/>'
    )

# The Palace of Chonga at the meeting of the rivers
x, y = 500, 610
w(f'''  <g stroke="#6b3d0c" stroke-width="5" stroke-linejoin="round">
    <rect x="{x - 46}" y="{y - 30}" width="92" height="52" fill="#ffd45c"/>
    <rect x="{x - 60}" y="{y - 58}" width="28" height="80" fill="#f5b82e"/>
    <rect x="{x + 32}" y="{y - 58}" width="28" height="80" fill="#f5b82e"/>
    <path d="M{x - 64} {y - 58} L{x - 46} {y - 88} L{x - 28} {y - 58} Z" fill="#e0344a"/>
    <path d="M{x + 28} {y - 58} L{x + 46} {y - 88} L{x + 64} {y - 58} Z" fill="#e0344a"/>
    <path d="M{x - 24} {y - 30} L{x} {y - 66} L{x + 24} {y - 30} Z" fill="#e0344a"/>
    <path d="M{x - 12} {y + 22} L{x - 12} {y - 2} Q{x} {y - 14} {x + 12} {y - 2} L{x + 12} {y + 22} Z" fill="#6b3d0c"/>
  </g>
  <path d="M{x} {y - 66} L{x} {y - 100}" stroke="#6b3d0c" stroke-width="5"/>
  <path d="M{x} {y - 100} L{x + 30} {y - 91} L{x} {y - 82} Z" fill="#7b4bc4" stroke="#6b3d0c" stroke-width="3"/>''')

# a pirate ("independent merchant") ship off the coast
x, y = 690, 885
w(f"""  <g stroke="#3a220f" stroke-width="5" stroke-linejoin="round" stroke-linecap="round">
    <path d="M{x - 55} {y} L{x + 55} {y} L{x + 38} {y + 28} L{x - 38} {y + 28} Z" fill="#8a4b23"/>
    <path d="M{x} {y} L{x} {y - 80}"/>
    <path d="M{x + 4} {y - 74} Q{x + 44} {y - 50} {x + 4} {y - 14} Z" fill="#fff6e0"/>
    <path d="M{x} {y - 80} L{x - 26} {y - 72} L{x} {y - 64} Z" fill="#1b1b1b"/>
  </g>
  <path d="M{x - 80} {y + 38} q15 -10 30 0 t30 0 t30 0 t30 0 t30 0" fill="none" stroke="#bfe9fb" stroke-width="5" stroke-linecap="round"/>""")

# little wave marks in the sea
for x, y in [(190, 250), (850, 280), (150, 780), (880, 800), (300, 920), (230, 140)]:
    w(
        f'  <path d="M{x} {y} q12 -9 24 0 t24 0" fill="none" stroke="#bfe9fb" stroke-width="5" stroke-linecap="round" opacity="0.6"/>'
    )

w("</svg>")
open("assets/chonga-map.svg", "w").write("\n".join(out) + "\n")
